window.AULAS["farma-gilmar-06"] = {"id": "farma-gilmar-06", "titulo": "Aula 6", "subtitulo": "Autacoides: histamina, serotonina, eicosanoides, PAF, cininas e AINEs", "pdf": "pdf/gilmar/aula-06.pdf", "abas": ["resumo", "glossario", "caso", "quiz", "tabela", "pdf"], "fontes": ["Aula 6 · Autacoides (Prof. Gilmar S. Erzinger)", "Brunton, Chabner e Knollmann (Goodman & Gilman); Nature Reviews Drug Discovery (citados nos slides)"], "resumo": [{"titulo": "1. Inflamação e autacoides", "pontos": ["Sinais cardinais: calor, rubor, edema, dor e perda de função (slide 3).", "Autacoides: substâncias naturais produzidas rapidamente em resposta a estímulos (histamina, serotonina, eicosanoides, PAF, cininas, citocinas) (slide 6)."]}, {"titulo": "2. Histamina e serotonina", "pontos": ["Histamina: H1 causa broncoconstrição, dilatação de vênulas, edema e prurido; H2 aumenta ácido gástrico; H3 é neurotransmissor no SNC (slide 9).", "Anti-histamínicos H1 de segunda geração têm menos sedação; ambas as gerações falham no angioedema hereditário e na vasculite urticariforme (slide 15).", "Serotonina: 5-HT3 da zona de gatilho é alvo da ondansetrona; 5-HT1B/1D causam vasoconstrição cerebral (triptanos) (slides 24 e 25)."]}, {"titulo": "3. Eicosanoides e cicloxigenases", "pontos": ["COX-1 constitutiva: citoproteção gástrica (PGE2), agregação plaquetária (TxA2), função renal. COX-2 induzida: dor e inflamação (slide 31).", "Via da lipoxigenase gera leucotrienos; via da COX gera prostaglandinas e tromboxanos (slide 29).", "PAF é de 100 a 1.000 vezes mais potente que a histamina (slide 36)."]}, {"titulo": "4. AINEs", "pontos": ["Mecanismo: inibição das cicloxigenases, reduzindo prostaglandinas (slide 58).", "Aspirina: inativação irreversível da COX por acetilação; antiagregante plaquetário (slide 60). Paracetamol: efeito central em COX-3, pouco anti-inflamatório (slide 61).", "Coxibes: inibidores seletivos da COX-2, com menos efeito gástrico, mas risco trombótico pelo desequilíbrio COX-1/COX-2 (slides 64, 65 e 69).", "Efeitos: TGI pela inibição da COX-1; renal, com nefropatia por analgésicos; cardiovascular; broncoespasmo em asmáticos sensíveis à aspirina (slides 67 a 70)."]}], "glossario": [{"termo": "Autacoide", "tecnica": "Conceito", "definicao": "Substância natural produzida rapidamente em resposta a estímulos, com ação local.", "slide": 6}, {"termo": "PAF", "tecnica": "Mediador lipídico", "definicao": "Fator ativador plaquetário, mediador fosfolipídico que aumenta a adesão celular, 100 a 1.000 vezes mais potente que a histamina.", "slide": 36}, {"termo": "COX-1 e COX-2", "tecnica": "Cicloxigenases", "definicao": "COX-1 constitutiva (estômago, plaquetas, rim); COX-2 induzida na inflamação; alvo dos AINEs.", "slide": 30}, {"termo": "Coxibes", "tecnica": "AINE seletivo", "definicao": "Inibidores seletivos da COX-2, como celecoxibe e rofecoxibe, com menos efeito gástrico.", "slide": 64}, {"termo": "Nefropatia associada a analgésicos", "tecnica": "Efeito renal", "definicao": "Lesão renal por uso contínuo de altas doses de AINEs, frequentemente irreversível.", "slide": 68}, {"termo": "5-HT3", "tecnica": "Receptor da serotonina", "definicao": "Canal iônico da zona de gatilho; alvo da ondansetrona contra náuseas.", "slide": 22}], "manobras": [], "caso": {"titulo": "Caso: asmático sensível à aspirina com dor", "perfil": "Broncoespasmo por AINE e risco de sangramento por COX-1.", "etapas": [{"titulo": "Etapa 1: broncoespasmo após AINE", "texto": "Mulher de 40 anos, asmática, toma ácido acetilsalicílico para cefaleia e evolui com broncoespasmo e sibilos minutos depois.", "perguntas": [{"pergunta": "Qual é o mecanismo mais provável do broncoespasmo, segundo a aula?", "erradas": {"A": "Receptores H2 não são o mecanismo do broncoespasmo descrito.", "C": "O ácido acetilsalicílico não atua como bloqueador beta-2.", "D": "Receptores 5-HT3 não são o mecanismo citado para a asma por AINE.", "E": "Inibir COX-2 reduz prostaglandinas, e não aumenta PGE2."}, "justificativa": "A aula cita broncoespasmo em asmáticos sensíveis à aspirina entre os efeitos dos AINEs (slide 70). O desvio para leucotrienos é um mecanismo comum da via da lipoxigenase (slide 29).", "alternativas": ["Ativação de receptores H2 brônquicos pela histamina liberada", "Inibição da COX com desvio do ácido araquidônico para leucotrienos broncoconstritores", "Bloqueio de receptores beta-2 pelo ácido acetilsalicílico", "Ativação de receptores 5-HT3 pulmonares pela serotonina", "Inibição da COX-2, que aumenta a produção de PGE2 brônquica"], "gabarito": "B"}]}, {"titulo": "Etapa 2: sangramento em idoso", "texto": "Homem de 72 anos, usando AINE não seletivo por artrose, tem melena e queda de hemoglobina. A endoscopia mostra úlcera gástrica.", "perguntas": [{"pergunta": "Qual é o mecanismo do sangramento, segundo a aula?", "erradas": {"A": "A inibição da COX-2 não é o mecanismo gastrointestinal central, segundo a aula.", "B": "Excesso de tromboxano não é o mecanismo descrito para a úlcera.", "C": "Histamina H1 não é o mecanismo de sangramento pelo AINE.", "D": "Receptores 5-HT4 estimulam a motilidade, e não causam a lesão descrita."}, "justificativa": "Os efeitos indesejados no TGI são principalmente pela inibição da COX-1 constitutiva, que suprime as prostaglandinas gastroprotetoras (slide 67).", "alternativas": ["Inibição da COX-2, com excesso de tromboxano na mucosa", "Ativação da histamina H1, com aumento da secreção gástrica", "Bloqueio dos receptores 5-HT4, com redução da motilidade", "Estímulo de PAF, com vasodilatação da submucosa", "Inibição da COX-1, com perda de prostaglandinas gastroprotetoras"], "gabarito": "E"}]}]}, "imagens": [], "casos_extremos": [], "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Quais são os sinais cardinais da inflamação, segundo a aula?", "alternativas": ["Febre, tosse, dispneia, calafrio e fadiga", "Hipotensão, taquicardia, cianose e sudorese", "Calor, rubor, edema, dor e perda de função", "Rash, prurido, urticária, edema labial e broncoespasmo", "Leucocitose, linfopenia, aumento de IgE e eosinofilia"], "gabarito": "C", "justificativa": "Os sinais cardinais são calor, rubor, edema (tumor), dor e perda de função (slide 3).", "tecnica": "Inflamação", "slide": 3}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Qual receptor de histamina, segundo a aula, causa aumento da permeabilidade e edema das vênulas?", "alternativas": ["H2, que aumenta a secreção de ácido gástrico", "H1, que causa dilatação das vênulas", "H3, que atua como neurotransmissor no SNC", "H4, que aumenta a diurese nos túbulos renais", "Nenhum, pois o edema depende apenas de prostaglandinas"], "gabarito": "B", "justificativa": "O receptor H1 causa dilatação das vênulas e contração endotelial, com edema e pápula (slide 9).", "tecnica": "Histamina", "slide": 9}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Qual é o efeito do receptor H2 do estômago, segundo a aula?", "alternativas": ["Redução da motilidade intestinal com constipação", "Broncoconstrição com aumento de muco", "Vasoconstrição cutânea com palidez", "Relaxamento do esfíncter esofágico inferior", "Aumento da secreção de ácido gástrico"], "gabarito": "E", "justificativa": "O receptor H2 aumenta a secreção de ácido gástrico (slide 9).", "tecnica": "Histamina", "slide": 9}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Qual é a principal diferença entre os anti-histamínicos H1 de primeira e segunda geração, segundo a aula?", "alternativas": ["Os de segunda geração são mais lipofílicos e causam mais sonolência", "A eficácia contra alergia é maior nos de primeira geração", "Os de segunda geração atuam apenas em receptores H2", "Os de primeira geração são mais lipofílicos", "Os de primeira geração não bloqueiam o aumento da permeabilidade"], "gabarito": "D", "justificativa": "Diferenças de lipofilicidade explicam a maior sedação dos de primeira geração; a eficácia é igual (slide 15).", "tecnica": "Anti-histamínicos H1", "slide": 15}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Os anti-histamínicos H1, segundo a aula, não são efetivos contra qual condição?", "alternativas": ["Rinite alérgica sazonal, urticária comum e prurido", "Conjuntivite alérgica e prurido cutâneo", "Pápulas e edema de origem histamínica", "Angioedema hereditário e vasculite urticariforme", "Espirros e coriza de origem alérgica"], "gabarito": "D", "justificativa": "Ambas as gerações de H1 não são efetivas contra a vasculite urticariforme e o angioedema hereditário (slide 15).", "tecnica": "Anti-histamínicos H1", "slide": 15}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Onde está a maior parte do conteúdo total de serotonina do organismo, segundo a aula?", "alternativas": ["Nos neurônios do córtex cerebral frontal", "Nas hemácias, em grande concentração", "Nas células enterocromafins intestinais", "No tecido adiposo, ligada à albumina", "Nos rins, na região do glomérulo"], "gabarito": "C", "justificativa": "Mais de 90% da serotonina do organismo está nas células enterocromafins do intestino (slide 20).", "tecnica": "Serotonina", "slide": 20}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Qual é o mecanismo do sumatriptano na enxaqueca, segundo a aula?", "alternativas": ["Antagonista de 5-HT3, com bloqueio da náusea central", "Agonista de 5-HT4, com aumento da motilidade intestinal", "Antagonista de H1, com redução do edema meníngeo", "Inibidor de COX-2, com redução da prostaglandina cerebral", "Agonista de 5-HT1B/1D, com vasoconstrição cerebral"], "gabarito": "E", "justificativa": "Os triptanos são agonistas de 5-HT1B/1D, com vasoconstrição cerebral e meníngea (slide 24).", "tecnica": "Triptanos", "slide": 24}, {"id": 8, "nivel": "muito_dificil", "enunciado": "A aspirina inibe a cicloxigenase de que forma, segundo a aula?", "alternativas": ["Inibição reversível e competitiva, com efeito curto", "Ligação à albumina, sem efeito direto sobre a COX", "Inativação irreversível, por acetilação da enzima", "Bloqueio dos receptores de prostaglandina na membrana", "Ativação transitória da COX-1, seguida de inibição"], "gabarito": "C", "justificativa": "A aspirina inativa a COX-1 e a COX-2 de forma irreversível, por acetilação (slide 60).", "tecnica": "Aspirina", "slide": 60}, {"id": 9, "nivel": "muito_dificil", "enunciado": "O paracetamol tem efeito antipirético e analgésico forte, mas pouco anti-inflamatório. A que subtipo de cicloxigenase a aula atribui esse perfil?", "alternativas": ["COX-1, de atuação no estômago", "COX-2, de atuação em macrófagos", "Lipoxigenase, de atuação em leucócitos", "Fosfolipase A2, de atuação na membrana", "COX-3, de atuação no SNC"], "gabarito": "E", "justificativa": "O perfil do paracetamol parece decorrer da atuação no SNC, em um subtipo de COX, a COX-3 (slide 61).", "tecnica": "Paracetamol", "slide": 61}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Por que os coxibes podem favorecer trombose, segundo a aula?", "alternativas": ["Inibem a COX-2; a COX-1 favorece a agregação", "Ativam a COX-1 e inibem a ação da prostaciclina", "Inibem a lipoxigenase e aumentam a agregação plaquetária", "Ativam o PAF, que causa vasoconstrição trombogênica", "Bloqueiam a agregação, mas aumentam a viscosidade sanguínea"], "gabarito": "A", "justificativa": "O desequilíbrio entre COX-1 e COX-2 favorece a agregação e a formação de trombos nos coxibes (slide 69).", "tecnica": "Coxibes", "slide": 69}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Qual é o mecanismo dos efeitos gastrointestinais dos AINEs, segundo a aula?", "alternativas": ["Inibição da COX-1 constitutiva", "Inibição da COX-2 nos macrófagos, com excesso de histamina", "Estimulação de receptores H2, com aumento da acidez gástrica", "Bloqueio de receptores 5-HT4, com redução da motilidade", "Ativação de receptores H1 no endotélio gástrico"], "gabarito": "A", "justificativa": "Os efeitos no TGI estão associados à inibição da COX-1 constitutiva (slide 67).", "tecnica": "Efeitos colaterais", "slide": 67}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Qual é a potência do PAF em relação à histamina, segundo a aula?", "alternativas": ["100 a 1.000 vezes mais potente", "Dez vezes menos potente", "Igual, pois ambos são aminas biogênicas", "Duas vezes mais potente, sem variação", "Mil vezes menos potente, por ser lipídico"], "gabarito": "A", "justificativa": "O PAF é de 100 a 1.000 vezes mais potente que a histamina (slide 36).", "tecnica": "PAF", "slide": 36}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Qual é a diferença entre os efeitos da PGE2 e da PGF2α, segundo a tabela da aula?", "alternativas": ["PGE2 contrai o miométrio; PGF2α causa vasodilatação sistêmica", "PGE2 causa vasodilatação; PGF2α contrai o miométrio", "PGE2 agrega plaquetas; PGF2α inibe a agregação", "PGE2 é produzida em plaquetas; PGF2α em macrófagos", "Ambas causam vasoconstrição e aumento da agregação plaquetária"], "gabarito": "B", "justificativa": "PGE2 causa vasodilatação e hiperalgesia; PGF2α contrai o miométrio, promove luteólise e broncoconstrição (slide 33).", "tecnica": "Prostanoides", "slide": 33}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que o uso contínuo de altas doses de AINEs pode causar lesão renal frequentemente irreversível?", "alternativas": ["Porque inibe a COX-1 plaquetária, aumentando a retenção de sódio", "Bloqueia prostaglandinas renais vasodilatadoras", "Porque ativa o PAF, que obstrui os glomérulos", "Porque aumenta a filtração de albumina, causando proteinúria", "Porque libera histamina nos túbulos, causando necrose"], "gabarito": "B", "justificativa": "As PGE2 e PGI2 renais são vasodilatadoras; seu bloqueio pode levar à nefropatia associada a analgésicos (slide 68).", "tecnica": "Efeitos renais", "slide": 68}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Qual AINE tem leve preferência pela COX-2, em baixas doses, segundo a aula?", "alternativas": ["Aspirina, com inativação irreversível de COX-1", "Paracetamol, com efeito central em COX-3", "Dipirona, com efeito sobre a lipoxigenase", "Meloxicam, na proporção de cerca de 10:1", "Ibuprofeno, com inibição igual de COX-1 e COX-2"], "gabarito": "D", "justificativa": "O meloxicam tem leve preferência pela COX-2 (cerca de 10:1) em baixas doses (slide 63).", "tecnica": "Oxicans", "slide": 63}], "voltar": {"href": "#/agressao/gilmar", "texto": "Professor Gilmar"}, "tabela": {"titulo": "Prostanoides: produção e ação (slide 33)", "colunas": ["Sigla", "Prostanoide", "Produção", "Ação"], "linhas": [["PGD2", "Prostaglandina D2", "Mastócitos", "Vasodilatação, inibição da agregação plaquetária, relaxamento do TGI e útero"], ["PGF2α", "Prostaglandina F2α", "Miométrio", "Contração do miométrio, luteólise e broncoconstrição"], ["PGI2", "Prostaciclina", "Endotélio", "Vasodilatação, hiperalgesia, inibição da agregação, renina e natriurese"], ["PGE2", "Prostaglandina E2", "Pulmão, macrófago", "Vasodilatação, hiperalgesia, febre, proliferação celular"], ["TXA2", "Tromboxano A2", "Plaquetas", "Agregação plaquetária, vasoconstrição e broncoconstrição"]]}};
